mapper.select:
SELECT *
FROM ai_knowledge_embedding_task
WHERE status = 0
  AND next_retry_time <= #{now}
ORDER BY next_retry_time ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE ai_knowledge_embedding_task
SET status = 1,
    processing_time = #{now},
    update_time = #{now}
WHERE id = #{id}
  AND status = 0
  AND next_retry_time <= #{now}

UPDATE ai_knowledge_embedding_task
SET status = 2,
    processing_time = NULL,
    success_time = #{now},
    last_error = NULL,
    update_time = #{now}
WHERE id = #{id}
  AND status = 1
  AND processing_time = #{processingTime}

UPDATE ai_knowledge_embedding_task
SET status = 4,
    processing_time = NULL,
    update_time = #{now}
WHERE knowledge_id = #{knowledgeId}
  AND status IN (0, 1)

UPDATE ai_knowledge_embedding_task
SET status = 4,
    processing_time = NULL,
    update_time = #{now}
WHERE id = #{id}
  AND status IN (0, 1)

UPDATE ai_knowledge_embedding_task
SET status = 0,
    next_retry_time = #{nextRetryTime},
    processing_time = NULL,
    update_time = #{now}
WHERE status = 1
  AND processing_time <= #{staleBefore}
ORDER BY processing_time ASC, id ASC
LIMIT #{limit}
